    b_shape = _shape_of(beta, 1, "beta")
    if b_shape[0] != g_shape[0]:
        raise ValueError(
            "beta 长度 %d 与 gamma 长度 %d 不符"
            % (b_shape[0], g_shape[0])
        )
    if isinstance(eps, bool) or not isinstance(eps, (int, float)):
        raise TypeError(
            "eps 必须是 int/float（拒绝 bool），得到 %s"
            % type(eps).__name__
        )
